sparql_response:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?father ?fatherLabel ?birthPlace ?birthPlaceLabel WHERE {
  ?father dbo:child <http://dbpedia.org/resource/David_Ogilvy,_12th_Earl_of_Airlie> .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER (lang(?fatherLabel) = "en") }
  ?father dbo:birthPlace ?birthPlace .
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER (lang(?birthPlaceLabel) = "en") }
}
LIMIT 100

